import { NextResponse } from 'next/server';
import { Resend } from 'resend';
import * as z from 'zod';

const contactSchema = z.object({
  firstName: z.string().min(1),
  lastName: z.string().min(1),
  email: z.string().email(),
  phone: z.string().optional(),
  message: z.string().min(1),
  contactType: z.enum(['investor', 'press', 'creator', 'job-seeker']),
});

const contactTypeLabels: Record<
  z.infer<typeof contactSchema>['contactType'],
  string
> = {
  investor: 'Investor',
  press: 'Press',
  creator: 'Creator',
  'job-seeker': 'Job Seeker',
};

const resend = new Resend(process.env.RESEND_API_KEY);
const RETRY_DELAYS_MS = [0, 5000, 10000];

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

const sendWithRetry = async (
  payload: Parameters<typeof resend.emails.send>[0],
) => {
  let lastError: unknown;

  for (let attempt = 0; attempt < RETRY_DELAYS_MS.length; attempt += 1) {
    if (attempt > 0) {
      await sleep(RETRY_DELAYS_MS[attempt]);
    }

    const { data, error } = await resend.emails.send(payload);

    if (!error) {
      return data;
    }

    lastError = error;
  }

  throw lastError ?? new Error('Unable to send contact email');
};

const FROM_EMAIL = 'info@benicapital.com';
const TO_EMAIL_ONE = 'mai@benicapital.com';
const TO_EMAIL_TWO = 'chaseinfo@benicapital.com';

export async function POST(request: Request) {
  if (!process.env.RESEND_API_KEY) {
    console.error('Missing contact email environment variables.');
    return NextResponse.json(
      { error: 'Email service is not configured.' },
      { status: 500 },
    );
  }

  let payload: z.infer<typeof contactSchema>;

  try {
    payload = contactSchema.parse(await request.json());
  } catch (error) {
    const details =
      error instanceof z.ZodError ? error.flatten().fieldErrors : undefined;

    return NextResponse.json(
      { error: 'Invalid contact form payload.', details },
      { status: 400 },
    );
  }

  const { firstName, lastName, email, phone, message, contactType } = payload;
  const contactLabel = contactTypeLabels[contactType];

  const plainText = [
    `Name: ${firstName} ${lastName}`,
    `Email: ${email}`,
    `Phone: ${phone || 'N/A'}`,
    `Contact type: ${contactLabel}`,
    '',
    message,
  ].join('\n');

  const html = `
    <h2>New contact form submission</h2>
    <p><strong>Name:</strong> ${firstName} ${lastName}</p>
    <p><strong>Email:</strong> ${email}</p>
    <p><strong>Phone:</strong> ${phone || 'N/A'}</p>
    <p><strong>Contact type:</strong> ${contactLabel}</p>
    <hr />
    <p>${message.replace(/\n/g, '<br />')}</p>
  `;

  try {
    await sendWithRetry({
      from: FROM_EMAIL,
      to: [TO_EMAIL_ONE, TO_EMAIL_TWO],
      subject: `Contact form submission (${contactLabel})`,
      replyTo: email,
      text: plainText,
      html,
    });

    return NextResponse.json({ ok: true });
  } catch (error) {
    console.error('Failed to send contact email.', error);
    return NextResponse.json(
      { error: 'Failed to send contact email.' },
      { status: 500 },
    );
  }
}

