/**
 * Fetches a single project by ID (public access)
 * @param projectId - The ID of the project to fetch
 * @returns The project data with its ID, or null if not found
 */
export async function getProjectById(
  projectId: string,
): Promise<(Project & { id: string }) | null> {
  try {
    const projectRef = doc(db, 'projects', projectId);
    const projectSnap = await getDoc(projectRef);

    if (projectSnap.exists()) {
      return {
        id: projectSnap.id,
        ...projectSnap.data(),
      } as Project & { id: string };
    } else {
      return null;
    }
  } catch (error) {
    console.error('Error fetching project:', error);
    throw error;
  }
}

/**
 * Fetches all projects (public access)
 * @returns An array of all projects with their IDs
 */
export async function getAllProjects(): Promise<Array<Project & { id: string }>> {
  try {
    const projectsCollection = collection(db, 'projects');
    const projectsSnapshot = await getDocs(projectsCollection);

    return projectsSnapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    })) as Array<Project & { id: string }>;
  } catch (error) {
    console.error('Error fetching projects:', error);
    throw error;
  }
}

import { collection, doc, setDoc } from 'firebase/firestore';
import { db } from './config';

/**
 * Creates a new transaction document in the root transactions collection
 * @param transaction - The transaction data (must include userId)
 * @returns The generated transaction ID
 */
export async function createTransaction(
  transaction: Transaction,
): Promise<string> {
  try {
    // Get root transactions collection reference
    const transactionsRef = collection(db, 'transactions');

    // Generate a new document reference with auto-generated ID from Firestore
    const newDocRef = doc(transactionsRef);
    const transactionId = newDocRef.id;

    // Write to root transactions collection
    await setDoc(newDocRef, transaction);

    return transactionId;
  } catch (error) {
    console.error('Error creating transaction:', error);
    throw error;
  }
}

/**
 * Creates an investment transaction
 * @param projectId - The project ID
 * @param projectName - The project name
 * @param amount - The investment amount
 * @param userId - The user ID
 * @param userEmail - The user email
 * @returns The generated transaction ID
 */
export async function createInvestmentTransaction(
  projectId: string,
  projectName: string,
  projectType: ProjectType,
  amount: number,
  userId: string,
  userEmail: string,
): Promise<string> {
  const transaction: Transaction = {
    type: 'investment',
    projectId,
    projectName,
    projectType,
    amount,
    date: Date.now(),
    userId,
    userEmail,
  };

  return createTransaction(transaction);
}

/**
 * Creates a return transaction
 * @param projectId - The project ID
 * @param projectName - The project name
 * @param amount - The return amount
 * @param userId - The user ID
 * @param userEmail - The user email
 * @returns The generated transaction ID
 */
export async function createReturnTransaction(
  projectId: string,
  projectName: string,
  projectType: ProjectType,
  amount: number,
  userId: string,
  userEmail: string,
): Promise<string> {
  const transaction: Transaction = {
    type: 'return',
    projectId,
    projectName,
    projectType,
    amount,
    date: Date.now(),
    userId,
    userEmail,
  };

  return createTransaction(transaction);
}

