import { deleteDoc, doc, getDoc, setDoc } from 'firebase/firestore';
import { db } from './config';

const waitlistDocId = (userId: string, projectId: string) =>
  `${userId}_${projectId}`;

export async function joinWaitlist(entry: WaitlistEntry): Promise<void> {
  try {
    const ref = doc(
      db,
      'waitlist',
      waitlistDocId(entry.userId, entry.projectId),
    );
    await setDoc(ref, entry);
  } catch (error) {
    console.error('Error joining waitlist:', error);
    throw error;
  }
}

export async function leaveWaitlist(
  userId: string,
  projectId: string,
): Promise<void> {
  try {
    const ref = doc(db, 'waitlist', waitlistDocId(userId, projectId));
    await deleteDoc(ref);
  } catch (error) {
    console.error('Error leaving waitlist:', error);
    throw error;
  }
}

export async function getWaitlistEntry(
  userId: string,
  projectId: string,
): Promise<WaitlistEntry | null> {
  try {
    const ref = doc(db, 'waitlist', waitlistDocId(userId, projectId));
    const snap = await getDoc(ref);
    return snap.exists() ? (snap.data() as WaitlistEntry) : null;
  } catch (error) {
    console.error('Error fetching waitlist entry:', error);
    throw error;
  }
}

