  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from 'modules/shared/table';
import { FC, useEffect, useState } from 'react';
import { AddReturnModal } from './AddReturnModal';

interface ReturnsProps {
  project: Project & { id: string };
}

export const Returns: FC<ReturnsProps> = ({ project }) => {
  const [returns, setReturns] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const fetchReturns = async () => {
    try {
      setLoading(true);
      const transactionsRef = collection(db, 'transactions');
      const q = query(
        transactionsRef,
        where('projectId', '==', project.id),
        where('type', '==', 'return'),
      );

      const querySnapshot = await getDocs(q);
      const fetchedReturns: Transaction[] = [];

      querySnapshot.forEach((doc) => {
        fetchedReturns.push(doc.data() as Transaction);
      });

      // Sort by date descending
      fetchedReturns.sort((a, b) => b.date - a.date);

      setReturns(fetchedReturns);
    } catch (error) {
      console.error('Error fetching returns:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchReturns();
  }, [project.id]);

  const handleReturnAdded = () => {
    fetchReturns();
  };

  // Group returns by userId
  const returnsByUser = returns.reduce(
    (acc, returnTransaction) => {
      if (!acc[returnTransaction.userId]) {
        acc[returnTransaction.userId] = [];
      }
      acc[returnTransaction.userId].push(returnTransaction);
      return acc;
    },
    {} as Record<string, Transaction[]>,
  );

  // Convert to array and sort by total returns (descending)
  const userGroups = Object.entries(returnsByUser)
    .map(([userId, userReturns]) => ({
      userId,
      userEmail: userReturns[0].userEmail,
      returns: userReturns,
      totalReturns: userReturns.reduce((sum, ret) => sum + ret.amount, 0),
    }))
    .sort((a, b) => b.totalReturns - a.totalReturns);

  const totalReturns = returns.reduce((sum, ret) => sum + ret.amount, 0);

  if (loading) {
    return (
      <div className="w-full bg-white rounded-[16px] shadow-lg p-40 flex items-center justify-center">
        <p className="text-gray-600">Loading returns...</p>
      </div>
    );
  }

  if (returns.length === 0) {
    return (
      <>
        <div className="w-full bg-white rounded-[16px] shadow-lg p-40 flex flex-col items-center justify-center">
          <p className="text-gray-600 mb-8">No returns yet</p>
          <p className="text-sm text-gray-500 mb-16">
            Returns for this project will appear here
          </p>
          <Button onClick={() => setIsModalOpen(true)}>
            <Plus className="mr-2 h-4 w-4" />
            Add Return
          </Button>
        </div>
        <AddReturnModal
          open={isModalOpen}
          onOpenChange={setIsModalOpen}
          project={project}
          onReturnAdded={handleReturnAdded}
        />
      </>
    );
  }

  return (
    <>
      <div className="w-full space-y-24">
        {/* Overall Summary */}
        <div className="bg-white rounded-[16px] shadow-lg p-24">
          <div className="flex justify-between items-center mb-12">
            <h2 className="text-[clamp(20px,22px)] leading-[clamp(24px,28px)] font-semibold">
              Returns Summary
            </h2>
            <Button onClick={() => setIsModalOpen(true)} size="small">
              <Plus className="mr-2 h-4 w-4" />
              Add Return
            </Button>
          </div>
          <div className="p-16 bg-green-50 rounded-lg">
            <p className="text-sm text-gray-600 mb-4">Total Returns</p>
            <p className="text-2xl font-bold text-green-600">
              {formatPrice(totalReturns)}
            </p>
            <p className="text-xs text-gray-500 mt-2">
              {returns.length} return{returns.length !== 1 ? 's' : ''} across{' '}
              {userGroups.length} investor{userGroups.length !== 1 ? 's' : ''}
            </p>
          </div>
        </div>

        {/* User-grouped Returns */}
        {userGroups.map((userGroup) => (
          <div
            key={userGroup.userId}
            className="bg-white rounded-[16px] shadow-lg p-24">
            <div className="mb-16">
              <div className="flex items-start justify-between mb-12">
                <div>
                  <h3 className="text-lg font-semibold mb-2">
                    {userGroup.userEmail}
                  </h3>
                  <p className="text-xs text-gray-500 font-mono">
                    {userGroup.userId}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-sm text-gray-600 mb-1">
                    {userGroup.returns.length} return
                    {userGroup.returns.length !== 1 ? 's' : ''}
                  </p>
                </div>
              </div>

              <div className="p-12 bg-green-50 rounded-lg">
                <p className="text-xs text-gray-600 mb-2">Total Returns</p>
                <p className="text-xl font-bold text-green-600">
                  {formatPrice(userGroup.totalReturns)}
                </p>
              </div>
            </div>

            <Table>
              <TableHeader>
                <TableRow className="h-60">
                  <TableHead className="font-semibold">Date</TableHead>
                  <TableHead className="font-semibold">Description</TableHead>
                  <TableHead className="font-semibold">Amount</TableHead>
                  <TableHead className="font-semibold">Account</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {userGroup.returns.map((returnTransaction, index) => (
                  <TableRow
                    key={`${returnTransaction.projectId}-${returnTransaction.userId}-${index}`}
                    className="h-60">
                    <TableCell className="text-sm">
                      {format(returnTransaction.date, 'MMM d, yyyy')}
                    </TableCell>
                    <TableCell className="text-sm font-medium text-green-600">
                      + {formatPrice(returnTransaction.amount)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        ))}
      </div>
      <AddReturnModal
        open={isModalOpen}
        onOpenChange={setIsModalOpen}
        project={project}
        onReturnAdded={handleReturnAdded}
      />
    </>
  );
};

