import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from 'lib/utils';
import * as React from 'react';

const buttonVariants = cva(
  "inline-flex items-center cursor-pointer justify-center gap-8 whitespace-nowrap rounded-[8px] font-semibold disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-16 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive  hover:scale-105 transition-all duration-300 ease-out",
  {
    variants: {
      variant: {
        default:
          'gold-panel text-[#222222] hover:gold-panel/90 rounded-full font-bold',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60',
        outline: 'border border-primary font-bold text-primary rounded-full',
        secondary: 'bg-offblack text-white hover:bg-offblack/80',
        ghost:
          'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        contrast:
          'bg-black text-primary hover:bg-black/90 rounded-full font-bold',
      },
      size: {
        default: 'h-32 px-12 py-6 has-[>svg]:px-12',
        small: 'h-44 gap-6 px-24 has-[>svg]:px-[10px]',
        large: 'h-56 px-40 has-[>svg]:px-16',
        xlarge: 'h-56 px-64 has-[>svg]:px-16',
        icon: 'size-16',
        'icon-sm': 'size-32',
        'icon-lg': 'size-40',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Comp = asChild ? Slot : 'button';

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

