1	import { INVESTMENT_TIERS } from 'const/investment-tiers';
2	import { createProduct, createProductPrice } from 'lib/easy-api/products';
3	import { getProjectById, updateProject } from 'lib/firebase/server-actions';
4	import { NextResponse } from 'next/server';
5	
6	export async function POST(request: Request) {
7	  let projectId: string;
8	
9	  try {
10	    const body = await request.json();
11	    projectId = body.projectId;
12	  } catch {
13	    return NextResponse.json({ error: 'Invalid request body.' }, { status: 400 });
14	  }
15	
16	  if (!projectId) {
17	    return NextResponse.json({ error: 'Missing projectId.' }, { status: 400 });
18	  }
19	
20	  const project = await getProjectById(projectId);
21	
22	  if (!project) {
23	    return NextResponse.json({ error: 'Project not found.' }, { status: 404 });
24	  }
25	
26	  const productResult = await createProduct({
27	    name: project.name,
28	    description: project.description,
29	    active: true,
30	    metadata: { projectId, app: 'beni-capital' },
31	    image_url: project.heroImage || '',
32	  });
33	
34	  if (!productResult.ok) {
35	    return NextResponse.json({ error: productResult.error }, { status: productResult.status });
36	  }
37	
38	  const productId = productResult.data.id;
39	  const priceIds: Record<string, string> = {};
40	
41	  for (const tier of INVESTMENT_TIERS) {
42	    const priceResult = await createProductPrice({
43	      product_id: productId,
44	      currency: 'USD',
45	      unit_amount: tier.cents,
46	      recurring: false,
47	      active: true,
48	      tax_behavior: 'exclusive',
49	      description: `${project.name} — $${tier.dollars.toLocaleString()} investment tier`,
50	      pricing_model: 'per_unit',
51	    });
52	
53	    if (!priceResult.ok) {
54	      return NextResponse.json({ error: priceResult.error }, { status: priceResult.status });
55	    }
56	
57	    priceIds[String(tier.dollars)] = priceResult.data.id;
58	  }
59	
60	  await updateProject(projectId, {
61	    easyApiProductId: productId,
62	    easyApiPriceIds: priceIds,
63	  });
64	
65	  const updatedProject = await getProjectById(projectId);
66	
67	  return NextResponse.json({ project: updatedProject });
68	}
